head.b:skin:
/* Modal de contraseña (sin cambios) */
.password-modal {
  position: fixed;
  top: 0; left: 0;
  width: 100%; height: 100%;
  background: rgba(0,0,0,0.9);
  z-index: 10000;
  display: flex;
  align-items: center;
  justify-content: center;
  font-family: 'Segoe UI', sans-serif;
}
.password-modal-content {
  background: #0a0a0a;
  border: 2px solid #ffaa00;
  border-radius: 20px;
  padding: 25px;
  width: 300px;
  text-align: center;
  color: white;
}
.password-modal input {
  width: 90%;
  padding: 10px;
  margin: 15px 0;
  background: #1a1a1a;
  border: 1px solid #ffaa00;
  color: white;
  border-radius: 8px;
}
.password-modal button {
  background: #ffaa00;
  color: #000;
  border: none;
  padding: 10px 20px;
  border-radius: 30px;
  cursor: pointer;
  font-weight: bold;
  margin: 5px;
}
.error-msg {
  color: #ff6666;
  font-size: 12px;
  margin-top: 10px;
}
/* Estilos generales */
body { margin: 0; padding: 0; background: #000000 !important; font-family: 'Segoe UI', Roboto, sans-serif; }
.ads-layout-wrapper { display: flex !important; justify-content: center !important; align-items: flex-start !important; gap: 20px !important; max-width: 1200px !important; margin: 20px auto !important; padding: 10px; }
.banner-lateral { width: 160px !important; min-height: 600px !important; background: rgba(0, 51, 204, 0.1) !important; display: flex !important; flex-direction: column !important; align-items: center !important; justify-content: center !important; border-radius: 10px !important; border: 1px dashed #0033cc !important; }
@media (max-width: 1024px) { .banner-lateral { display: none !important; } }
.latam-sports-card { background-color: #0a0a0a !important; color: #ffffff !important; width: 100% !important; max-width: 480px !important; border-radius: 15px !important; overflow: hidden !important; border: 1px solid #0033cc !important; box-shadow: 0 0 20px rgba(0, 51, 204, 0.3) !important; flex-shrink: 0 !important; }
.latam-header { background: #001133 !important; padding: 20px 15px !important; text-align: center !important; border-bottom: 1px solid #0033cc; }
/* Componente unificado más pequeño con pulso de escala y resplandor */
.live-stats {
  display: inline-flex;
  margin: 10px auto 0;
  border-radius: 16px;
  background: rgba(0,0,0,0.3);
  overflow: hidden;
  border: 1px solid #ff3333;
  cursor: pointer;
  font-size: 10px;
}
.btn-en-vivo {
  background: #ff0000;
  color: #ffffff;
  padding: 2px 6px;
  font-size: 9px;
  font-weight: bold;
  text-transform: uppercase;
  letter-spacing: 0.3px;
  border: none;
  animation: pulse-glow 1.2s infinite ease-in-out;
}
@keyframes pulse-glow {
  0% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(255, 0, 0, 0.7);
  }
  50% {
    transform: scale(1.05);
    box-shadow: 0 0 0 6px rgba(255, 0, 0, 0);
  }
  100% {
    transform: scale(1);
    box-shadow: 0 0 0 0 rgba(255, 0, 0, 0);
  }
}
.viewer-counter {
  background: rgba(0,0,0,0.6);
  color: #ff6666;
  padding: 2px 8px;
  font-size: 9px;
  font-weight: bold;
  display: inline-flex;
  align-items: center;
  gap: 3px;
  border-left: 1px solid #ff3333;
}
.viewer-counter span {
  color: #ffffff;
  margin: 0 1px;
}
.viewer-counter svg {
  width: 10px;
  height: 10px;
  fill: #ff6666;
}
.latam-content { padding: 20px !important; }
.latam-match-title { font-size: 20px !important; font-weight: 800 !important; text-align: center !important; margin-bottom: 15px !important; display: flex !important; justify-content: center !important; align-items: center !important; gap: 10px !important; color: #ffffff; }
.video-container { position: relative !important; width: 100% !important; border-radius: 10px !important; overflow: hidden !important; margin-bottom: 20px !important; cursor: pointer !important; background: #000; border: 1px solid #0033cc; }
.video-img { width: 100% !important; display: block !important; transition: all 0.5s ease !important; opacity: 0.8; }
.video-container:hover .video-img { transform: scale(1.1) rotate(1deg) !important; opacity: 1 !important; }
.play-overlay { position: absolute !important; top: 50% !important; left: 50% !important; transform: translate(-50%, -50%) !important; width: 70px !important; height: 70px !important; background: rgba(0, 0, 0, 0.7) !important; border-radius: 50% !important; display: flex !important; align-items: center !important; justify-content: center !important; border: 3px solid #0033cc !important; transition: all 0.3s !important; }
.video-container:hover .play-overlay { background: #0033cc !important; transform: translate(-50%, -50%) scale(1.1) !important; }
.channels-box { background: #000 !important; border: 1px dashed #0033cc !important; border-radius: 8px !important; padding: 10px !important; margin-bottom: 15px !important; font-size: 14px !important; text-align: center !important; color: #ccc; }
.latam-schedule { background: #000 !important; border-radius: 10px !important; padding: 12px !important; margin-bottom: 20px !important; border: 1px solid #222; }
.schedule-grid { display: grid !important; grid-template-columns: 1fr 1fr !important; gap: 8px !important; font-size: 13px !important; }
.schedule-item { display: flex !important; justify-content: space-between !important; border-bottom: 1px solid #0033cc !important; padding: 4px 0 !important; color: #ccc; }
.btn-premium { display: block !important; background: linear-gradient(135deg, #ff0000, #cc0000) !important; color: #ffffff !important; text-align: center !important; text-decoration: none !important; padding: 18px !important; border-radius: 10px !important; font-weight: 800 !important; font-size: 1.2rem !important; position: relative !important; overflow: hidden !important; box-shadow: 0 0 15px rgba(255, 0, 0, 0.5) !important; animation: pulse-scale 2s infinite !important; margin-top: 15px; }
.btn-premium::after { content: "" !important; position: absolute !important; top: -50% !important; left: -150% !important; width: 200% !important; height: 200% !important; background: rgba(255, 255, 255, 0.2) !important; transform: rotate(45deg) !important; animation: shine 3s infinite !important; }
@keyframes shine { 0% { left: -150%; } 20% { left: 150%; } 100% { left: 150%; } }
@keyframes pulse-scale { 0% { transform: scale(1); } 50% { transform: scale(1.02); } 100% { transform: scale(1); } }
.bet-section { background: #000; border: 1px solid #0033cc; border-radius: 16px; padding: 15px; margin: 20px 0; box-shadow: 0 0 10px rgba(0, 51, 204, 0.3); }
.bet-title { text-align: center; font-size: 18px; font-weight: bold; color: #0033cc; margin-bottom: 15px; }
.bet-buttons { display: flex; gap: 12px; margin-bottom: 20px; }
.bet-btn { flex: 1; padding: 12px; border: none; border-radius: 40px; font-weight: bold; cursor: pointer; transition: 0.3s; }
.bet-btn-local { background: linear-gradient(135deg, #0033cc, #0022aa); color: white; }
.bet-btn-visit { background: linear-gradient(135deg, #aa00ff, #7700cc); color: white; }
.bet-btn:hover { transform: scale(1.02); filter: brightness(1.1); }
.bet-btn-disabled { opacity: 0.6; cursor: not-allowed; }
.result-bar-container { margin: 10px 0; }
.result-label { display: flex; justify-content: space-between; font-size: 13px; margin-bottom: 5px; color: #ccc; }
.result-bar { height: 28px; background: #1a1a1a; border-radius: 30px; overflow: hidden; }
.result-fill { height: 100%; width: 0%; transition: width 0.5s; display: flex; align-items: center; justify-content: flex-end; padding-right: 8px; font-size: 12px; color: white; }
.fill-local { background: linear-gradient(90deg, #0033cc, #0022aa); }
.fill-visit { background: linear-gradient(90deg, #aa00ff, #7700cc); }
.total-votes { text-align: center; margin-top: 12px; font-size: 12px; color: #888; border-top: 1px solid #222; padding-top: 10px; }
.admin-panel { background: #0a0a0a; border: 2px solid #ffaa00; border-radius: 16px; padding: 20px; margin-top: 20px; display: none; }
.admin-panel h4 { color: #ffaa00; margin-bottom: 15px; text-align: center; }
.admin-menu { display: flex; flex-direction: column; gap: 10px; margin-bottom: 20px; }
.admin-menu-btn { background: #1a1a1a; border: 1px solid #ffaa00; color: #ffaa00; padding: 12px; border-radius: 10px; cursor: pointer; font-weight: bold; text-align: left; transition: 0.3s; }
.admin-menu-btn:hover { background: #ffaa00; color: #000; }
.admin-section { display: none; border-top: 1px solid #333; padding-top: 15px; margin-top: 10px; }
.admin-input-group { display: flex; gap: 10px; margin: 10px 0; align-items: center; flex-wrap: wrap; }
.admin-input-group input { background: #1a1a1a; border: 1px solid #ffaa00; color: white; padding: 8px; border-radius: 8px; flex: 1; }
.admin-input-group label { min-width: 80px; color: #ffaa00; }
.admin-btn { background: #ffaa00; color: #000; border: none; padding: 8px 16px; border-radius: 8px; cursor: pointer; font-weight: bold; }
.admin-btn-danger { background: #ff3300; color: white; }
.admin-close { text-align: center; margin-top: 15px; cursor: pointer; color: #ffaa00; font-size: 12px; }
.schedule-editor { display: grid; gap: 8px; }
.schedule-row { display: flex; gap: 10px; align-items: center; }
.schedule-row input { flex: 1; background: #1a1a1a; border: 1px solid #ffaa00; color: white; padding: 6px; border-radius: 6px; }
.sticky-ad-bottom { position: fixed; bottom: 0; left: 0; width: 100%; background: #000; border-top: 2px solid #0033cc; z-index: 999; text-align: center; padding: 8px; color: #ffffff; }
.close-sticky { position: absolute; right: 10px; top: -25px; background: #0033cc; color: #fff; border-radius: 50%; width: 24px; height: 24px; cursor: pointer; line-height: 22px; font-weight: bold; }
.sticky-ad-bottom a { color: #0033cc !important; text-decoration: none; font-weight: bold; margin-left: 5px; }
.sticky-ad-bottom a:hover { text-decoration: underline; }
.futstream-title {
  font-family: 'Montserrat', sans-serif;
  font-weight: 700;
  font-size: 34px;
  background: linear-gradient(135deg, #ffffff, #aaccff);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 0 8px rgba(0, 102, 255, 0.8);
  letter-spacing: 1px;
  margin: 0;
  line-height: 1.2;
  display: flex;
  justify-content: center;
  align-items: baseline;
  gap: 8px;
  flex-wrap: wrap;
}
.futstream-title .hd {
  font-size: 20px;
  background: linear-gradient(135deg, #ffdd88, #ffaa22);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: 0 0 6px rgba(255, 170, 34, 0.8);
  font-weight: 800;
}
.ad-under-video {
  text-align: center;
  margin: 15px auto;
  display: flex;
  justify-content: center;
}

div.script:
//
const API_URL = "https://script.google.com/macros/s/AKfycbzISO0cDHdJs-AiT_9x5N1JB0ocJNdUT9wJJdzQdyIOdTYRCotmO0lDugRWZV-hpQQz/exec"; // <-- REEMPLAZA CON TU URL

let votosLocal = 0, votosVisit = 0, usuarioVoto = null;
let equipoLocal = "REAL MADRID", equipoVisit = "BARCELONA";
let linkStream = "#", linkAfiliado = "#", linkBotonHD = "#";
let textoCanales = "ESPN, Star+, DSports y Sky Sports";
let imagenUrl = "";
let horariosData = [];
let adminPassword = "";
let adminAuthenticated = false;

function formatNumber(num) {
  return num.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
}

function initViewerCounter() {
  let viewers = localStorage.getItem('liveViewers');
  if (!viewers) {
    viewers = 1436;
    localStorage.setItem('liveViewers', viewers);
  } else {
    viewers = parseInt(viewers, 10);
  }
  const viewerSpan = document.getElementById('viewerCount');
  if (viewerSpan) viewerSpan.innerText = formatNumber(viewers);

  setInterval(() => {
    let increment = Math.floor(Math.random() * 8) + 1;
    viewers += increment;
    localStorage.setItem('liveViewers', viewers);
    if (viewerSpan) viewerSpan.innerText = formatNumber(viewers);
  }, Math.random() * 5000 + 7000);
}

async function cargarTodo() {
  try {
    let resp = await fetch(API_URL);
    let datos = await resp.json();
    votosLocal = datos.local || 0;
    votosVisit = datos.visit || 0;
    equipoLocal = datos.equipoLocal || "REAL MADRID";
    equipoVisit = datos.equipoVisit || "BARCELONA";
    linkStream = datos.linkStream || "#";
    linkAfiliado = datos.linkAfiliado || "#";
    linkBotonHD = datos.linkBotonHD || "#";
    textoCanales = datos.canales || "ESPN, Star+, DSports y Sky Sports";
    imagenUrl = datos.imagenUrl || "";
    horariosData = datos.horarios || [
      {pais:"🇲🇽 MEX/GUA", hora:"13:00"},
      {pais:"🇨🇴 COL/ECU", hora:"14:00"},
      {pais:"🇵🇪 PERÚ", hora:"14:00"},
      {pais:"🇻🇪 VEN/DOM", hora:"15:00"},
      {pais:"🇵🇾 PARAGUAY", hora:"16:00"},
      {pais:"🇦🇷 ARG/URU", hora:"16:00"},
      {pais:"🇧🇷 BRASIL (BSB)", hora:"16:00"},
      {pais:"🇪🇸 ESPAÑA", hora:"21:00"}
    ];
    adminPassword = datos.password || "";
    actualizarInterfazCompleta();
    initViewerCounter();
  } catch(e) { 
    document.getElementById('totalVotesText').innerHTML = '⚠️ Error al cargar datos';
    console.error(e);
  }
}

function actualizarInterfazCompleta() {
  document.getElementById('teamLocalSpan').innerHTML = equipoLocal;
  document.getElementById('teamVisitSpan').innerHTML = equipoVisit;
  document.getElementById('btnLocal').innerHTML = `🏆 ${equipoLocal}`;
  document.getElementById('btnVisit').innerHTML = `🌟 ${equipoVisit}`;
  document.getElementById('localNameLabel').innerHTML = equipoLocal;
  document.getElementById('visitNameLabel').innerHTML = equipoVisit;
  document.getElementById('videoLink').href = linkStream;
  let stickyLink = document.querySelector('.sticky-ad-bottom a');
  if(stickyLink) stickyLink.href = linkAfiliado;
  let botonHD = document.getElementById('streamingLink');
  if(botonHD) botonHD.href = linkBotonHD;
  document.querySelector('.channels-box').innerHTML = `📺 Canales: ${textoCanales}`;
  if(imagenUrl) document.getElementById('videoImg').src = imagenUrl;
  actualizarTablaHorarios();
  actualizarUI();
}

function actualizarUI() {
  let total = votosLocal + votosVisit;
  let porcLocal = total === 0 ? 0 : (votosLocal / total * 100).toFixed(1);
  let porcVisit = total === 0 ? 0 : (votosVisit / total * 100).toFixed(1);
  document.getElementById('localFill').style.width = porcLocal + '%';
  document.getElementById('localFill').innerHTML = votosLocal;
  document.getElementById('visitFill').style.width = porcVisit + '%';
  document.getElementById('visitFill').innerHTML = votosVisit;
  document.getElementById('localPercent').innerHTML = porcLocal + '%';
  document.getElementById('visitPercent').innerHTML = porcVisit + '%';
  document.getElementById('totalVotesText').innerHTML = `⚡ ${total} personas han apostado ⚡`;
  if(usuarioVoto) {
    document.getElementById('btnLocal').disabled = true;
    document.getElementById('btnVisit').disabled = true;
    document.getElementById('btnLocal').classList.add('bet-btn-disabled');
    document.getElementById('btnVisit').classList.add('bet-btn-disabled');
  } else {
    document.getElementById('btnLocal').disabled = false;
    document.getElementById('btnVisit').disabled = false;
    document.getElementById('btnLocal').classList.remove('bet-btn-disabled');
    document.getElementById('btnVisit').classList.remove('bet-btn-disabled');
  }
}

async function guardarVotosEnSheet(local, visit) {
  try { await fetch(API_URL, { method: 'POST', mode: 'no-cors', headers: {'Content-Type': 'application/json'}, body: JSON.stringify({local, visit}) }); return true; } catch(e) { return false; }
}
async function guardarConfigEnSheet(config) {
  try { await fetch(API_URL, { method: 'POST', mode: 'no-cors', headers: {'Content-Type': 'application/json'}, body: JSON.stringify(config) }); return true; } catch(e) { return false; }
}

async function votar(equipo) {
  if(usuarioVoto) { alert('⚠️ Ya votaste en este partido'); return; }
  if(equipo === 'local') votosLocal++; else votosVisit++;
  let ok = await guardarVotosEnSheet(votosLocal, votosVisit);
  if(ok) { usuarioVoto = equipo; localStorage.setItem('userVoted', equipo); actualizarUI(); alert('✅ Voto registrado'); }
  else { if(equipo === 'local') votosLocal--; else votosVisit--; alert('❌ Error, intenta de nuevo'); }
}

async function guardarVotosAdmin() {
  let nuevoLocal = parseInt(document.getElementById('adminLocalVotos').value) || 0;
  let nuevoVisit = parseInt(document.getElementById('adminVisitVotos').value) || 0;
  votosLocal = nuevoLocal; votosVisit = nuevoVisit;
  await guardarVotosEnSheet(votosLocal, votosVisit);
  actualizarUI();
  alert('✅ Votos actualizados globalmente');
}
async function reiniciarVotosAdmin() {
  if(confirm('⚠️ ¿Reiniciar todas las apuestas?')) {
    votosLocal = 0; votosVisit = 0;
    await guardarVotosEnSheet(0, 0);
    localStorage.removeItem('userVoted'); usuarioVoto = null;
    actualizarUI();
    alert('✅ Apuestas reiniciadas');
  }
}
async function guardarEquiposAdmin() {
  let local = document.getElementById('adminTeamLocal').value;
  let visit = document.getElementById('adminTeamVisit').value;
  equipoLocal = local; equipoVisit = visit;
  await guardarConfigEnSheet({ equipoLocal: local, equipoVisit: visit });
  actualizarInterfazCompleta();
  alert('✅ Equipos actualizados globalmente');
}
async function guardarEnlacesAdmin() {
  let stream = document.getElementById('adminStreamLink').value;
  let aff = document.getElementById('adminAffLink').value;
  let botonHD = document.getElementById('adminBotonHDLink').value;
  linkStream = stream; linkAfiliado = aff; linkBotonHD = botonHD;
  await guardarConfigEnSheet({ linkStream: stream, linkAfiliado: aff, linkBotonHD: botonHD });
  actualizarInterfazCompleta();
  alert('✅ Enlaces actualizados globalmente');
}
async function guardarCanalesAdmin() {
  let canales = document.getElementById('adminCanalesText').value;
  textoCanales = canales;
  await guardarConfigEnSheet({ canales: canales });
  actualizarInterfazCompleta();
  alert('✅ Canales actualizados globalmente');
}
async function guardarHorariosAdmin() {
  let nuevos = [];
  for(let i=0; i<horariosData.length; i++) {
    let pais = document.getElementById(`horarioPais${i}`).value;
    let hora = document.getElementById(`horarioHora${i}`).value;
    nuevos.push({pais, hora});
  }
  horariosData = nuevos;
  await guardarConfigEnSheet({ horarios: horariosData });
  actualizarInterfazCompleta();
  alert('✅ Horarios actualizados globalmente');
}
async function guardarImagenAdmin() {
  let url = document.getElementById('adminImageUrl').value;
  imagenUrl = url;
  await guardarConfigEnSheet({ imagenUrl: url });
  actualizarInterfazCompleta();
  alert('✅ Imagen actualizada globalmente');
}

async function cambiarPassword() {
  let newPwd = document.getElementById('newPasswordInput').value;
  let confirmPwd = document.getElementById('confirmPasswordInput').value;
  if (!newPwd) { alert('Escribe una contraseña'); return; }
  if (newPwd !== confirmPwd) { alert('Las contraseñas no coinciden'); return; }
  await guardarConfigEnSheet({ newPassword: newPwd });
  adminPassword = newPwd;
  alert('✅ Contraseña cambiada correctamente');
  document.getElementById('newPasswordInput').value = '';
  document.getElementById('confirmPasswordInput').value = '';
}

function actualizarTablaHorarios() {
  let grid = document.querySelector('.schedule-grid');
  if(grid) {
    grid.innerHTML = '';
    horariosData.forEach(item => {
      let div = document.createElement('div');
      div.className = 'schedule-item';
      div.innerHTML = `<span>${item.pais}</span> <span>${item.hora}</span>`;
      grid.appendChild(div);
    });
  }
}
function renderizarEditorHorarios() {
  let cont = document.getElementById('editHorariosContainer');
  cont.innerHTML = '';
  horariosData.forEach((item, idx) => {
    let div = document.createElement('div');
    div.className = 'schedule-row';
    div.innerHTML = `<input type='text' value='${item.pais}' id='horarioPais${idx}' style='flex:2'/><input type='text' value='${item.hora}' id='horarioHora${idx}' style='flex:1'/>`;
    cont.appendChild(div);
  });
}
function mostrarSeccion(seccion) {
  let ids = ['votos','equipos','enlaces','canales','horarios','imagen','password'];
  ids.forEach(s => { let el = document.getElementById(`seccion${s.charAt(0).toUpperCase() + s.slice(1)}`); if(el) el.style.display = 'none'; });
  let target = document.getElementById(`seccion${seccion.charAt(0).toUpperCase() + seccion.slice(1)}`);
  if(target) target.style.display = 'block';
  if(seccion === 'horarios') renderizarEditorHorarios();
}
function cerrarPanelAdmin() { document.getElementById('adminPanel').style.display = 'none'; }

function mostrarModalPassword() {
  let modal = document.createElement('div');
  modal.className = 'password-modal';
  modal.innerHTML = `
    <div class='password-modal-content'>
      <h3>🔐 Acceso restringido</h3>
      <p>Ingresa la contraseña de administrador:</p>
      <input type='password' id='adminPasswordInput' placeholder='Contraseña'/>
      <div><button id='btnSubmitPwd'>Aceptar</button></div>
      <div class='error-msg' id='pwdError'></div>
    </div>
  `;
  document.body.appendChild(modal);
  document.getElementById('btnSubmitPwd').onclick = () => {
    let pwd = document.getElementById('adminPasswordInput').value;
    if (pwd === adminPassword) {
      adminAuthenticated = true;
      modal.remove();
      document.getElementById('adminPanel').style.display = 'block';
      document.getElementById('adminLocalVotos').value = votosLocal;
      document.getElementById('adminVisitVotos').value = votosVisit;
      document.getElementById('adminTeamLocal').value = equipoLocal;
      document.getElementById('adminTeamVisit').value = equipoVisit;
      document.getElementById('adminStreamLink').value = linkStream;
      document.getElementById('adminAffLink').value = linkAfiliado;
      document.getElementById('adminBotonHDLink').value = linkBotonHD;
      document.getElementById('adminCanalesText').value = textoCanales;
      document.getElementById('adminImageUrl').value = imagenUrl;
    } else {
      document.getElementById('pwdError').innerText = '❌ Contraseña incorrecta';
    }
  };
}

let contadorClicks = 0, temporizador;
let liveElement = document.getElementById('liveStatsButton');
if(liveElement) {
  liveElement.addEventListener('click', function() {
    contadorClicks++;
    clearTimeout(temporizador);
    if(contadorClicks === 5) {
      if (!adminAuthenticated) {
        mostrarModalPassword();
      } else {
        let panel = document.getElementById('adminPanel');
        if(panel.style.display === 'none' || panel.style.display === '') {
          panel.style.display = 'block';
        } else {
          panel.style.display = 'none';
        }
      }
      contadorClicks = 0;
    }
    temporizador = setTimeout(() => { contadorClicks = 0; }, 1000);
  });
}

document.getElementById('btnLocal').onclick = () => votar('local');
document.getElementById('btnVisit').onclick = () => votar('visit');
cargarTodo();
//

b:includable.script:
    (function() {
      var items = ;
      var msgs = ;
      var config = ;

// 
      var cursor = null;
      if (items && items.length > 0) {
        cursor = parseInt(items[items.length - 1].timestamp) + 1;
      }

      var bodyFromEntry = function(entry) {
        var text = (entry &&
                    ((entry.content && entry.content.$t) ||
                     (entry.summary && entry.summary.$t))) ||
            '';
        if (entry && entry.gd$extendedProperty) {
          for (var k in entry.gd$extendedProperty) {
            if (entry.gd$extendedProperty[k].name == 'blogger.contentRemoved') {
              return '<span class="deleted-comment">' + text + '</span>';
            }
          }
        }
        return text;
      }

      var parse = function(data) {
        cursor = null;
        var comments = [];
        if (data && data.feed && data.feed.entry) {
          for (var i = 0, entry; entry = data.feed.entry[i]; i++) {
            var comment = {};
            // comment ID, parsed out of the original id format
            var id = /blog-(\d+).post-(\d+)/.exec(entry.id.$t);
            comment.id = id ? id[2] : null;
            comment.body = bodyFromEntry(entry);
            comment.timestamp = Date.parse(entry.published.$t) + '';
            if (entry.author && entry.author.constructor === Array) {
              var auth = entry.author[0];
              if (auth) {
                comment.author = {
                  name: (auth.name ? auth.name.$t : undefined),
                  profileUrl: (auth.uri ? auth.uri.$t : undefined),
                  avatarUrl: (auth.gd$image ? auth.gd$image.src : undefined)
                };
              }
            }
            if (entry.link) {
              if (entry.link[2]) {
                comment.link = comment.permalink = entry.link[2].href;
              }
              if (entry.link[3]) {
                var pid = /.*comments\/default\/(\d+)\?.*/.exec(entry.link[3].href);
                if (pid && pid[1]) {
                  comment.parentId = pid[1];
                }
              }
            }
            comment.deleteclass = 'item-control blog-admin';
            if (entry.gd$extendedProperty) {
              for (var k in entry.gd$extendedProperty) {
                if (entry.gd$extendedProperty[k].name == 'blogger.itemClass') {
                  comment.deleteclass += ' ' + entry.gd$extendedProperty[k].value;
                } else if (entry.gd$extendedProperty[k].name == 'blogger.displayTime') {
                  comment.displayTime = entry.gd$extendedProperty[k].value;
                }
              }
            }
            comments.push(comment);
          }
        }
        return comments;
      };

      var paginator = function(callback) {
        if (hasMore()) {
          var url = config.feed + '?alt=json&v=2&orderby=published&reverse=false&max-results=50';
          if (cursor) {
            url += '&published-min=' + new Date(cursor).toISOString();
          }
          window.bloggercomments = function(data) {
            var parsed = parse(data);
            cursor = parsed.length < 50 ? null
                : parseInt(parsed[parsed.length - 1].timestamp) + 1
            callback(parsed);
            window.bloggercomments = null;
          }
          url += '&callback=bloggercomments';
          var script = document.createElement('script');
          script.type = 'text/javascript';
          script.src = url;
          document.getElementsByTagName('head')[0].appendChild(script);
        }
      };
      var hasMore = function() {
        return !!cursor;
      };
      var getMeta = function(key, comment) {
        if ('iswriter' == key) {
          var matches = !!comment.author
              && comment.author.name == config.authorName
              && comment.author.profileUrl == config.authorUrl;
          return matches ? 'true' : '';
        } else if ('deletelink' == key) {
          return config.baseUri + '/comment/delete/'
               + config.blogId + '/' + comment.id;
        } else if ('deleteclass' == key) {
          return comment.deleteclass;
        }
        return '';
      };

      var replybox = null;
      var replyUrlParts = null;
      var replyParent = undefined;

      var onReply = function(commentId, domId) {
        if (replybox == null) {
          // lazily cache replybox, and adjust to suit this style:
          replybox = document.getElementById('comment-editor');
          if (replybox != null) {
            replybox.height = '250px';
            replybox.style.display = 'block';
            replyUrlParts = replybox.src.split('#');
          }
        }
        if (replybox && (commentId !== replyParent)) {
          replybox.src = '';
          document.getElementById(domId).insertBefore(replybox, null);
          replybox.src = replyUrlParts[0]
              + (commentId ? '&parentID=' + commentId : '')
              + '#' + replyUrlParts[1];
          replyParent = commentId;
        }
      };

      var hash = (window.location.hash || '#').substring(1);
      var startThread, targetComment;
      if (/^comment-form_/.test(hash)) {
        startThread = hash.substring('comment-form_'.length);
      } else if (/^c[0-9]+$/.test(hash)) {
        targetComment = hash.substring(1);
      }

      // Configure commenting API:
      var configJso = {
        'maxDepth': config.maxThreadDepth
      };
      var provider = {
        'id': config.postId,
        'data': items,
        'loadNext': paginator,
        'hasMore': hasMore,
        'getMeta': getMeta,
        'onReply': onReply,
        'rendered': true,
        'initComment': targetComment,
        'initReplyThread': startThread,
        'config': configJso,
        'messages': msgs
      };

      var render = function() {
        if (window.goog && window.goog.comments) {
          var holder = document.getElementById('comment-holder');
          window.goog.comments.render(holder, provider);
        }
      };

      // render now, or queue to render when library loads:
      if (window.goog && window.goog.comments) {
        render();
      } else {
        window.goog = window.goog || {};
        window.goog.comments = window.goog.comments || {};
        window.goog.comments.loadQueue = window.goog.comments.loadQueue || [];
        window.goog.comments.loadQueue.push(render);
      }
    })();
//
